const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Rectangle([-118.61, 34.03, -118.46, 34.16], null, false); // NW of Pacific Palisades
    const scaleCoarse = 1000; // Best-practice coarse scale for robust reductions
    const maxPixels = 1e9;

    // AOI area (km2)
    const aoiAreaDict = await ee.Image.pixelArea().divide(1e6).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scaleCoarse,
      maxPixels: maxPixels
    }).getInfo();
    const aoiAreaKm2 = aoiAreaDict ? aoiAreaDict['area'] || aoiAreaDict['sum'] : null;
    const aoiKm2 = (typeof aoiAreaKm2 === 'number') ? aoiAreaKm2 : null;
    console.log(`AOI km²: ${aoiKm2 !== null ? aoiKm2.toFixed(2) : 'NA'}`);

    // 2. Primary Data: MODIS Burned Area (MCD64A1), Jan 2025
    const modisCol = ee.ImageCollection('MODIS/061/MCD64A1')
      .filterDate('2025-01-01', '2025-02-01')
      .filterBounds(aoi);
    const modisCount = await modisCol.size().getInfo();
    console.log(`MODIS MCD64A1 (2025-01) images: ${modisCount}`);

    if (!modisCount || modisCount === 0) {
      // Fallback to Sentinel-2 NBR
      console.log('MODIS not available. Falling back to Sentinel-2.');

      const win1Start = '2025-01-03', win1End = '2025-01-09';
      const win2Start = '2025-01-11', win2End = '2025-01-17';
      const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED').filterBounds(aoi);

      function maskS2(img) {
        const qa = img.select('QA60');
        const cloud = qa.bitwiseAnd(1 << 10).eq(0);
        const cirrus = qa.bitwiseAnd(1 << 11).eq(0);
        const scaled = img.divide(10000);
        return scaled.updateMask(cloud.and(cirrus));
      }
      function nbr(img) {
        return img.normalizedDifference(['B8', 'B12']).rename('NBR');
      }
      function composite(start, end) {
        const col = s2.filterDate(start, end).map(maskS2);
        return col.median().select(['B8', 'B12']).addBands(nbr(col.median()));
      }

      const col1 = s2.filterDate(win1Start, win1End);
      const col2 = s2.filterDate(win2Start, win2End);
      const n1 = await col1.size().getInfo();
      const n2 = await col2.size().getInfo();
      console.log(`S2 images (Jan6 win): ${n1 || 0}`);
      console.log(`S2 images (Jan14 win): ${n2 || 0}`);

      if (!n1 || !n2) {
        console.log('One or both S2 windows empty.');
        console.log('C1');
        return;
      }

      const img1 = composite(win1Start, win1End);
      const img2 = composite(win2Start, win2End);

      // Valid pixel counts (NBR band)
      const count1Dict = await img1.select('NBR').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scaleCoarse,
        maxPixels: maxPixels
      }).getInfo();
      const count2Dict = await img2.select('NBR').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scaleCoarse,
        maxPixels: maxPixels
      }).getInfo();
      const count1 = count1Dict ? (count1Dict.NBR || count1Dict.count) : 0;
      const count2 = count2Dict ? (count2Dict.NBR || count2Dict.count) : 0;
      console.log(`Valid px @1km (Jan6, Jan14): ${count1 || 0}, ${count2 || 0}`);

      if (!count1 || !count2) {
        console.log('No valid pixels after masking.');
        console.log('C2');
        return;
      }

      // Burned area proxy: NBR < 0.1 (lower NBR implies burn/char)
      const burn1 = img1.select('NBR').lt(0.1);
      const burn2 = img2.select('NBR').lt(0.1);

      const area1Dict = await ee.Image.pixelArea().divide(1e4).updateMask(burn1).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scaleCoarse,
        maxPixels: maxPixels
      }).getInfo();
      const area2Dict = await ee.Image.pixelArea().divide(1e4).updateMask(burn2).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scaleCoarse,
        maxPixels: maxPixels
      }).getInfo();
      const area1 = area1Dict ? (area1Dict.sum || area1Dict.area) : null;
      const area2 = area2Dict ? (area2Dict.sum || area2Dict.area) : null;

      if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
        console.log('Burn area calculation invalid.');
        console.log('C3');
        return;
      }

      const delta = area2 - area1;
      console.log(`Burned area ha (Jan6): ${area1.toFixed(2)}`);
      console.log(`Burned area ha (Jan14): ${area2.toFixed(2)}`);
      console.log(`Delta ha (Jan14 - Jan6): ${delta.toFixed(2)}`);

      if (delta > 1.0) {
        console.log('A');
      } else {
        console.log('B');
      }
      return;
    }

    // Use MODIS BurnDate
    const burnImg = ee.Image(modisCol.first()).select('BurnDate');
    // Total pixel count at 1km
    const totalPxDict = await ee.Image(1).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scaleCoarse,
      maxPixels: maxPixels
    }).getInfo();
    const totalPx = totalPxDict ? (totalPxDict.constant || totalPxDict.count) : null;
    console.log(`Pixels @1km in AOI: ${totalPx !== null ? totalPx : 0}`);

    const burn6 = burnImg.gt(0).and(burnImg.lte(6));
    const burn14 = burnImg.gt(0).and(burnImg.lte(14));

    const area6Dict = await ee.Image.pixelArea().divide(1e4).updateMask(burn6).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scaleCoarse,
      maxPixels: maxPixels
    }).getInfo();
    const area14Dict = await ee.Image.pixelArea().divide(1e4).updateMask(burn14).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scaleCoarse,
      maxPixels: maxPixels
    }).getInfo();

    const area6 = area6Dict ? (area6Dict.sum || area6Dict.area) : 0;
    const area14 = area14Dict ? (area14Dict.sum || area14Dict.area) : 0;

    if (area6 === null || area14 === null || isNaN(area6) || isNaN(area14)) {
      console.log('Invalid MODIS burned area result.');
      console.log('C3');
      return;
    }

    const delta = area14 - area6;
    console.log(`Burned area ha (≤ Jan 6): ${area6.toFixed(2)}`);
    console.log(`Burned area ha (≤ Jan 14): ${area14.toFixed(2)}`);
    console.log(`Delta ha (≤14 - ≤6): ${delta.toFixed(2)}`);

    if (delta > 1.0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
